// Simple Orbit Escape game
// Canvas with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.clientWidth || 800;
  const H = canvas.height = canvas.clientHeight || 600;

  // Ship state
  const ship = {
    x: W / 2,
    y: H * 0.8,
    angle: 0,
    radius: 10,
    thrust: 0,
    vx: 0,
    vy: 0,
    fuel: 100,
    shield: false,

